% Ultrasound Signal Analysis - Voltage (Time) to Magnitude (dB) vs. Frequency (MHz)

% 1. Load the Ultrasound Signal (Replace with your data loading)
% Assuming your data is in a file named 'ultrasound_data.mat'
% and contains 'time' (in seconds) and 'voltage' (in Volts) variables.

if exist('ultrasound_data.mat', 'file')
    load('ultrasound_data.mat');
    % Check if time and voltage variables exist
    if ~exist('time', 'var') || ~exist('voltage', 'var')
        error('The loaded data file must contain ''time'' and ''voltage'' variables.');
    end
else
    % Example data generation (for demonstration purposes)
    % Replace this with your actual data loading!
    Fs = 20e6; % Sampling Frequency (Example: 20 MHz)
    duration = 1e-6; % Duration of signal (Example: 1 microsecond)
    time = 0:1/Fs:duration-1/Fs;
    f0 = 5e6; % Center frequency of the ultrasound pulse (Example: 5 MHz)
    voltage = sin(2*pi*f0*time) .* gausswin(length(time), 0.2)';  % Gaussian pulse
    disp('Using example data.  Please load your own data file.');
end




% 2. Signal Preprocessing (Optional but Recommended)

% Detrending (remove DC offset)
voltage = voltage - mean(voltage);

% Windowing (optional - reduces spectral leakage) - Choose an appropriate window
window = hamming(length(voltage));  % Example: Hamming window
voltage_windowed = voltage .* window; %Apply window
%voltage_windowed = voltage;  % Or don't window if you don't need it.


% 3. Fast Fourier Transform (FFT)
N = length(voltage);  % Number of samples
Fs = 1/(time(2) - time(1)); % Calculate Sampling Frequency from time vector
f = Fs*(0:(N/2))/N;      % Frequency vector (Positive frequencies only)

Y = fft(voltage_windowed);
P2 = abs(Y/N);
P1 = P2(1:N/2+1);  % Single-sided amplitude spectrum;
P1(2:end-1) = 2*P1(2:end-1); % Correct for single-sided spectrum.



% 4. Convert Magnitude to Decibels (dB)
magnitude_dB = 20*log10(P1);


% 5. Convert Frequency to MHz
frequency_MHz = f / 1e6;


% 6. Plot the Result

figure;
plot(frequency_MHz, magnitude_dB);
xlabel('Frequency (MHz)');
ylabel('Magnitude (dB)');
title('Ultrasound Signal Spectrum');
grid on;



% --- Helper function (optional) to visually inspect your signal

function inspect_signal(time, voltage, Fs)
    figure;

    % Time Domain Plot
    subplot(2, 1, 1);
    plot(time, voltage);
    xlabel('Time (s)');
    ylabel('Voltage (V)');
    title('Ultrasound Signal - Time Domain');
    grid on;

    % Basic Spectrum Analysis (Unscaled)
    N = length(voltage);
    f = Fs*(0:(N/2))/N;
    Y = fft(voltage);
    P2 = abs(Y/N);
    P1 = P2(1:N/2+1);
    P1(2:end-1) = 2*P1(2:end-1);
    subplot(2, 1, 2);
    plot(f/1e6, P1); % Frequency in MHz
    xlabel('Frequency (MHz)');
    ylabel('Magnitude');
    title('Unscaled Spectrum');
    grid on;

    sgtitle('Signal Inspection'); % Overall figure title
end


% --- Example usage of the inspection function (optional)

% If you want to quickly check the signal and a basic spectrum *before*
% applying the detailed analysis code:
%
% Fs = 1/(time(2) - time(1)); % Calculate Sampling Frequency from time vector
% inspect_signal(time, voltage, Fs);




```

